"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import { BookOpen, Clock, Users, ChevronRight, Loader2, Target, CheckCircle2, Star, ShieldCheck } from "lucide-react";
import api from "@/lib/api";
import toast from "react-hot-toast";
import { useAuth } from "@/context/AuthContext";

interface Course {
  id: string;
  title: string;
  description: string;
  instructor: { name: string };
  lessons: { id: string, title: string }[];
  _count?: { enrollments: number };
}

export default function CourseDetailsPage() {
  const { id } = useParams();
  const router = useRouter();
  const { user } = useAuth();
  const [course, setCourse] = useState<Course | null>(null);
  const [loading, setLoading] = useState(true);
  const [enrolling, setEnrolling] = useState(false);
  const [isEnrolled, setIsEnrolled] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [courseRes, enrolledRes] = await Promise.all([
          api.get(`/courses/${id}`),
          user ? api.get("/courses/enrolled") : Promise.resolve({ data: [] })
        ]);

        setCourse(courseRes.data);
        if (user) {
          const alreadyEnrolled = enrolledRes.data.some((c: any) => c.id === id);
          setIsEnrolled(alreadyEnrolled);
        }
      } catch (err) {
        toast.error("Failed to load course details");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [id, user]);

  const handleEnroll = async () => {
    if (!user) {
      router.push(`/login?redirect=/courses/${id}`);
      return;
    }

    setEnrolling(true);
    try {
      await api.post(`/courses/${id}/enroll`);
      toast.success("Successfully enrolled!");
      setIsEnrolled(true);
      router.push(`/dashboard/student/courses/${id}`);
    } catch (err: any) {
      toast.error(err.response?.data?.error || "Enrollment failed");
    } finally {
      setEnrolling(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={40} />
      </div>
    );
  }

  if (!course) return null;

  return (
    <main className="min-h-screen bg-background">
      <Navbar />

      <section className="pt-32 pb-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">

            {/* Left Content */}
            <div className="lg:col-span-2 space-y-12">
              <div>
                <span className="inline-block bg-primary/10 text-primary text-xs font-black uppercase tracking-[0.2em] px-3 py-1 rounded-md mb-6">
                  Course Overview
                </span>
                <h1 className="text-4xl md:text-5xl font-black tracking-tight mb-6 leading-tight">
                  {course.title}
                </h1>
                <p className="text-xl text-muted-foreground leading-relaxed">
                  {course.description}
                </p>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                {[
                  { icon: Clock, label: "Duration", value: "Self-paced" },
                  { icon: BookOpen, label: "Lessons", value: `${course.lessons.length} Modules` },
                  { icon: Users, label: "Students", value: course._count?.enrollments || 0 },
                  { icon: Star, label: "Rating", value: "4.9/5.0" }
                ].map((stat, i) => (
                  <div key={i} className="glass p-4 rounded-2xl border border-border">
                    <stat.icon className="text-primary mb-2" size={20} />
                    <p className="text-[10px] uppercase font-bold text-muted-foreground">{stat.label}</p>
                    <p className="font-bold">{stat.value}</p>
                  </div>
                ))}
              </div>

              <div className="space-y-6">
                <h2 className="text-2xl font-bold flex items-center gap-3">
                  <Target className="text-primary" />
                  What you&apos;ll learn
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {[
                    "Master core concepts with AI Tutoring",
                    "Real-world project implementations",
                    "AI-generated personalized quizzes",
                    "Structured lesson summaries"
                  ].map((item, i) => (
                    <div key={i} className="flex items-center gap-3 text-muted-foreground">
                      <CheckCircle2 className="text-green-500 flex-shrink-0" size={18} />
                      <span className="text-sm">{item}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-6">
                <h2 className="text-2xl font-bold">Curriculum</h2>
                <div className="space-y-3">
                  {course.lessons.map((lesson, i) => (
                    <div key={lesson.id} className="glass p-5 rounded-xl border border-border flex justify-between items-center group hover:border-primary/30 transition-all">
                      <div className="flex items-center gap-4">
                        <span className="text-xs font-black text-primary bg-primary/10 w-8 h-8 flex items-center justify-center rounded-lg">
                          {i + 1}
                        </span>
                        <span className="font-bold group-hover:text-primary transition-colors">{lesson.title}</span>
                      </div>
                      <ShieldCheck size={18} className="text-muted-foreground/30" />
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Right Sidebar - Enrollment */}
            <div className="lg:col-span-1">
              <div className="sticky top-32 glass p-8 rounded-3xl border border-border shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 blur-[50px] -z-10 group-hover:bg-primary/20 transition-all" />

                <div className="space-y-8">
                  <div className="space-y-2">
                    <div className="flex items-baseline gap-2">
                      <span className="text-4xl font-black">Free</span>
                      <span className="text-muted-foreground line-through text-lg">$99.00</span>
                    </div>
                    <p className="text-sm text-muted-foreground font-medium">Limited time offer for AI Smart members.</p>
                  </div>

                  <button
                    onClick={isEnrolled ? () => router.push(`/dashboard/student/courses/${id}`) : handleEnroll}
                    disabled={enrolling}
                    className="w-full bg-primary text-white py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 hover:neon-glow transition-all disabled:opacity-50"
                  >
                    {enrolling ? (
                      <Loader2 className="animate-spin" />
                    ) : isEnrolled ? (
                      <>
                        <span>Go to Course</span>
                        <ChevronRight size={20} />
                      </>
                    ) : (
                      <>
                        <span>Enroll Now</span>
                        <ChevronRight size={20} />
                      </>
                    )}
                  </button>

                  <div className="space-y-4">
                    <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground text-center">Includes</p>
                    <div className="space-y-3">
                      {[
                        "Full lifetime access",
                        "Personal AI Tutor",
                        "Smart Study Plans",
                        "Certificate of Completion"
                      ].map((feature, i) => (
                        <div key={i} className="flex items-center gap-3 text-sm">
                          <CheckCircle2 className="text-primary" size={16} />
                          <span className="font-medium">{feature}</span>
                        </div>
                      ))}
                    </div>
                  </div>

                  <p className="text-[10px] text-center text-muted-foreground leading-relaxed">
                    By enrolling, you agree to AI SMART&apos;s terms of service and privacy policy.
                  </p>
                </div>
              </div>
            </div>

          </div>
        </div>
      </section>

      <Footer />
    </main>
  );
}

"use client";

import { useState, useEffect } from "react";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import { BookOpen, Clock, Users, Search, ChevronRight, Loader2 } from "lucide-react";
import Link from "next/link";
import api from "@/lib/api";

interface Course {
  id: string;
  title: string;
  description: string;
  instructor: { name: string };
  lessons: { id: string }[];
  _count?: { enrollments: number };
  level?: string;
}

export default function CoursesPage() {
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const res = await api.get("/courses");
        setCourses(res.data);
      } catch (err) {
        console.error("Failed to fetch courses", err);
      } finally {
        setLoading(false);
      }
    };
    fetchCourses();
  }, []);

  const filtered = courses.filter(c => 
    c.title.toLowerCase().includes(search.toLowerCase()) ||
    c.description.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <main className="min-h-screen bg-background">
      <Navbar />

      <section className="pt-32 pb-16 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-96 h-96 bg-primary/10 rounded-full blur-[120px] -z-10" />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12">
            <span className="inline-block text-primary text-sm font-bold uppercase tracking-widest mb-4">Course Catalog</span>
            <h1 className="text-5xl md:text-6xl font-extrabold tracking-tight mb-4 text-foreground">
              Learn Anything, <br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-red-400">Master Everything</span>
            </h1>
            <p className="text-muted-foreground text-xl max-w-2xl mx-auto">
              Browse our AI-curated course library. Every course includes quizzes, smart notes, and personal AI tutoring.
            </p>
          </div>

          {/* Search & Filter */}
          <div className="max-w-2xl mx-auto mb-16">
            <div className="relative">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-muted-foreground" size={20} />
              <input
                type="text"
                placeholder="Search courses, topics, instructors..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full bg-muted border-none rounded-2xl py-4 pl-14 pr-6 focus:ring-2 focus:ring-primary outline-none text-lg text-foreground"
              />
            </div>
          </div>

          {loading ? (
            <div className="flex justify-center py-20">
              <Loader2 className="animate-spin text-primary w-12 h-12" />
            </div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-20 glass rounded-3xl border border-border">
              <BookOpen className="mx-auto text-muted-foreground mb-4" size={48} />
              <h3 className="text-xl font-bold">No courses found</h3>
              <p className="text-muted-foreground mt-2">Try adjusting your search terms.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {filtered.map((course, i) => (
                <div key={course.id} className="group glass rounded-2xl border border-border hover:border-primary/30 overflow-hidden transition-all">
                  <div className="relative h-44 bg-primary/10 overflow-hidden">
                    <div className="absolute inset-0 bg-gradient-to-br from-primary/40 to-red-400/30" />
                    <div className="absolute inset-0 flex items-center justify-center">
                      <BookOpen size={44} className="text-white/40" />
                    </div>
                    <span className="absolute top-4 right-4 bg-black/50 text-white text-xs px-3 py-1 rounded-full font-medium">
                      {course.level || "Beginner"}
                    </span>
                  </div>
                  <div className="p-6 space-y-4">
                    <div>
                      <h3 className="font-bold text-lg leading-tight mb-1 group-hover:text-primary transition-colors text-foreground">{course.title}</h3>
                      <p className="text-sm text-muted-foreground">by {course.instructor?.name || "AI Tutor"}</p>
                    </div>
                    <div className="flex items-center justify-between text-xs text-muted-foreground">
                      <span className="flex items-center space-x-1"><Clock size={12} /><span>{course.lessons?.length || 0} lessons</span></span>
                      <span className="flex items-center space-x-1"><Users size={12} /><span>{(course._count?.enrollments || 0).toLocaleString()} students</span></span>
                    </div>
                    <Link href={`/courses/${course.id}`} className="flex items-center justify-between text-sm bg-primary/10 text-primary px-4 py-2.5 rounded-xl font-medium hover:bg-primary hover:text-white transition-all group/btn">
                      <span>Learn More</span>
                      <ChevronRight size={16} className="group-hover/btn:translate-x-1 transition-transform" />
                    </Link>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      <Footer />
    </main>
  );
}

"use client";

import { useAuth } from "@/context/AuthContext";
import { useRouter, usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import Link from "next/link";
import {
  LayoutDashboard, Users, BookOpen,
  LogOut, Shield, ChevronRight, Menu, X, Loader2, GraduationCap, UserCircle
} from "lucide-react";

import ProtectedRoute from "@/components/auth/ProtectedRoute";

const adminNav = [
  { href: "/dashboard/admin", label: "Overview", icon: LayoutDashboard },
  { href: "/dashboard/admin/users", label: "Users", icon: Users },
  { href: "/dashboard/admin/courses", label: "Courses", icon: BookOpen },
  { href: "/dashboard/instructor", label: "Instructor Mode", icon: GraduationCap },
  { href: "/dashboard/student", label: "Student Mode", icon: UserCircle },
];

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const { user, dbUser, loading, logout } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => { setSidebarOpen(false); }, [pathname]);

  if (!user && !loading) return null;

  return (
    <ProtectedRoute allowedRoles={["ADMIN"]}>
      <div className="min-h-screen flex bg-background">
      {/* Mobile overlay */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/60 z-30 lg:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Sidebar */}
      <aside className={`fixed top-0 left-0 h-full w-64 z-40 bg-card border-r border-border flex flex-col transition-transform duration-300 ${sidebarOpen ? "translate-x-0" : "-translate-x-full"} lg:translate-x-0 lg:static lg:z-auto`}>
        <div className="p-6 border-b border-border flex items-center justify-between">
          <Link href="/" className="flex items-center space-x-2">
            <div className="w-9 h-9 bg-primary rounded-xl flex items-center justify-center">
              <Shield className="text-white w-5 h-5" />
            </div>
            <span className="font-bold text-lg">Admin Panel</span>
          </Link>
          <button className="lg:hidden text-muted-foreground hover:text-foreground" onClick={() => setSidebarOpen(false)}>
            <X size={20} />
          </button>
        </div>

        <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
          {adminNav.map(({ href, label, icon: Icon }) => {
            const active = pathname === href;
            return (
              <Link
                key={href}
                href={href}
                onClick={() => setSidebarOpen(false)}
                className={`flex items-center space-x-3 px-4 py-3 rounded-xl font-medium transition-all ${
                  active ? "bg-primary text-white shadow-lg shadow-primary/20" : "text-muted-foreground hover:text-foreground hover:bg-muted"
                }`}
              >
                <Icon size={18} />
                <span>{label}</span>
                {active && <ChevronRight size={16} className="ml-auto" />}
              </Link>
            );
          })}
        </nav>

        <div className="p-4 border-t border-border">
          <div className="flex items-center space-x-3 mb-4 px-2">
            <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold">
              {user?.displayName?.charAt(0) || user?.email?.charAt(0).toUpperCase() || "A"}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-bold truncate">{user?.displayName || "Administrator"}</p>
              <div className="flex items-center space-x-1.5">
                <span className="px-1.5 py-0.5 rounded bg-primary text-white text-[10px] font-bold uppercase tracking-wider">
                  {dbUser?.role || 'ADMIN'}
                </span>
                <p className="text-[10px] text-muted-foreground truncate">{user?.email}</p>
              </div>
            </div>
          </div>
          <button
            onClick={logout}
            className="w-full flex items-center space-x-3 px-4 py-3 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors font-medium"
          >
            <LogOut size={18} />
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Mobile header */}
        <header className="lg:hidden sticky top-0 z-20 bg-card/80 backdrop-blur-xl border-b border-border px-4 py-3 flex items-center justify-between">
          <button onClick={() => setSidebarOpen(true)} className="p-2 rounded-xl hover:bg-muted">
            <Menu size={22} />
          </button>
          <span className="font-bold">Admin Panel</span>
          <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-sm">
            {user?.displayName?.charAt(0) || "A"}
          </div>
        </header>

        <main className="flex-1 p-6 lg:p-8">
          {children}
        </main>
      </div>
    </div>
    </ProtectedRoute>
  );
}

