"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { BookOpen, Users, Plus, Loader2, Search, Eye, Edit2, ToggleLeft, ToggleRight } from "lucide-react";
import api from "@/lib/api";
import Link from "next/link";
import toast from "react-hot-toast";
import { useAuth } from "@/context/AuthContext";

interface Course {
  id: string;
  title: string;
  description: string;
  published: boolean;
  lessons: { id: string }[];
  enrollments: { id: string }[];
  createdAt: string;
}

export default function InstructorCoursesPage() {
  const { user } = useAuth();
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  const fetchCourses = async () => {
    try {
      const res = await api.get("/courses/instructor");
      setCourses(res.data);
    } catch {
      toast.error("Failed to load courses");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!user) return;
    fetchCourses();
  }, [user]);

  const handleDeleteCourse = async (id: string) => {
    if (!confirm("Are you sure you want to delete this course? All data including student enrollments will be lost.")) return;

    try {
      await api.delete(`/courses/${id}`);
      toast.success("Course deleted successfully");
      setCourses(courses.filter(c => c.id !== id));
    } catch (error) {
      toast.error("Failed to delete course");
    }
  };

  const handleTogglePublish = async (course: Course) => {
    try {
      const res = await api.patch(`/courses/${course.id}`, {
        published: !course.published
      });
      setCourses(courses.map(c => c.id === course.id ? res.data : c));
      toast.success(res.data.published ? "Course published" : "Course unpublished");
    } catch (error) {
      toast.error("Failed to update status");
    }
  };

  const filtered = courses.filter((c) =>
    c.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-8">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">My Courses</h1>
          <p className="text-muted-foreground mt-2">Manage and track all your courses.</p>
        </div>
        <Link
          href="/dashboard/instructor/courses/new"
          className="bg-primary text-white px-5 py-2.5 rounded-xl font-medium hover:bg-primary/90 transition-all flex items-center space-x-2"
        >
          <Plus size={18} />
          <span>Create Course</span>
        </Link>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {[
          { label: "Total Courses", value: courses.length, icon: BookOpen },
          { label: "Total Students", value: courses.reduce((s, c) => s + (c.enrollments?.length || 0), 0), icon: Users },
          { label: "Total Lessons", value: courses.reduce((s, c) => s + (c.lessons?.length || 0), 0), icon: BookOpen },
        ].map((stat) => (
          <div key={stat.label} className="glass p-5 rounded-2xl border border-border flex items-center space-x-4">
            <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center text-primary">
              <stat.icon size={22} />
            </div>
            <div>
              <p className="text-2xl font-bold">{stat.value}</p>
              <p className="text-sm text-muted-foreground">{stat.label}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground" size={18} />
        <input
          type="text"
          placeholder="Search your courses..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full bg-muted border-none rounded-xl py-3 pl-11 pr-4 focus:ring-2 focus:ring-primary outline-none"
        />
      </div>

      {loading ? (
        <div className="space-y-6 animate-pulse">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[1, 2, 3].map(i => <div key={i} className="h-24 bg-muted rounded-2xl" />)}
          </div>
          <div className="h-12 w-full bg-muted rounded-xl" />
          <div className="h-96 bg-muted rounded-2xl" />
        </div>
      ) : (
        <div className="glass rounded-2xl border border-border overflow-hidden">
          {filtered.length === 0 ? (
            <div className="p-16 text-center">
              <BookOpen size={40} className="text-muted-foreground mx-auto mb-4" />
              <h3 className="font-bold text-lg mb-2">No courses yet</h3>
              <p className="text-muted-foreground mb-6">Create your first AI-generated course.</p>
              <Link href="/dashboard/instructor/courses/new" className="bg-primary text-white px-6 py-2.5 rounded-xl font-medium hover:bg-primary/90 transition-colors inline-flex items-center space-x-2">
                <Plus size={18} />
                <span>Create Course</span>
              </Link>
            </div>
          ) : (
            <table className="w-full">
              <thead className="bg-muted/50 border-b border-border">
                <tr>
                  <th className="text-left py-3 px-6 text-xs font-bold uppercase tracking-wider text-muted-foreground">Course</th>
                  <th className="text-left py-3 px-6 text-xs font-bold uppercase tracking-wider text-muted-foreground hidden md:table-cell">Lessons</th>
                  <th className="text-left py-3 px-6 text-xs font-bold uppercase tracking-wider text-muted-foreground hidden md:table-cell">Students</th>
                  <th className="text-left py-3 px-6 text-xs font-bold uppercase tracking-wider text-muted-foreground">Status</th>
                  <th className="text-right py-3 px-6 text-xs font-bold uppercase tracking-wider text-muted-foreground">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {filtered.map((course, i) => (
                  <motion.tr
                    key={course.id}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: i * 0.05 }}
                    className="hover:bg-muted/30 transition-colors"
                  >
                    <td className="py-4 px-6">
                      <div>
                        <p className="font-medium line-clamp-1">{course.title}</p>
                        <p className="text-xs text-muted-foreground line-clamp-1 mt-0.5">{course.description}</p>
                      </div>
                    </td>
                    <td className="py-4 px-6 hidden md:table-cell">
                      <span className="text-sm">{course.lessons?.length || 0}</span>
                    </td>
                    <td className="py-4 px-6 hidden md:table-cell">
                      <span className="text-sm">{course.enrollments?.length || 0}</span>
                    </td>
                    <td className="py-4 px-6">
                      <button 
                        onClick={() => handleTogglePublish(course)}
                        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium cursor-pointer transition-colors ${course.published ? "bg-green-500/10 text-green-500 hover:bg-green-500/20" : "bg-muted text-muted-foreground hover:bg-muted/80"}`}
                      >
                        {course.published ? "Published" : "Draft"}
                      </button>
                    </td>
                    <td className="py-4 px-6 text-right">
                      <div className="flex items-center justify-end space-x-2">
                        <Link href={`/dashboard/instructor/courses/${course.id}`} className="p-2 hover:bg-muted rounded-lg transition-colors text-muted-foreground hover:text-primary" title="View/Edit Lessons">
                          <Eye size={16} />
                        </Link>
                        <button 
                          onClick={() => handleDeleteCourse(course.id)}
                          className="p-2 hover:bg-red-500/10 rounded-lg transition-colors text-muted-foreground hover:text-red-500"
                          title="Delete Course"
                        >
                          <Plus size={16} className="rotate-45" />
                        </button>
                      </div>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useAuth } from "@/context/AuthContext";
import { useRouter, usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import {
  Loader2, LayoutDashboard, BookOpen, Users,
  LogOut, FilePlus, Menu, X, ChevronRight, GraduationCap
} from "lucide-react";
import Link from "next/link";
import ProtectedRoute from "@/components/auth/ProtectedRoute";

const navItems = [
  { name: "Overview", href: "/dashboard/instructor", icon: LayoutDashboard, exact: true },
  { name: "My Courses", href: "/dashboard/instructor/courses", icon: BookOpen },
  { name: "Create Course", href: "/dashboard/instructor/courses/new", icon: FilePlus },
  { name: "Students", href: "/dashboard/instructor/students", icon: Users },
];

export default function InstructorDashboardLayout({ children }: { children: React.ReactNode }) {
  const { user, dbUser, loading, logout } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => { setSidebarOpen(false); }, [pathname]);

  if (!user && !loading) return null;

  const SidebarContent = () => (
    <>
      {/* Brand */}
      <div className="p-6 border-b border-border flex items-center justify-between">
        <Link href="/" className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center">
            <GraduationCap className="text-white w-4 h-4" />
          </div>
          <div>
            <span className="text-xl font-bold tracking-tight">AI<span className="text-primary">Smart</span></span>
            <span className="block text-xs text-muted-foreground -mt-0.5">Instructor</span>
          </div>
        </Link>
        <button
          className="md:hidden text-muted-foreground hover:text-foreground"
          onClick={() => setSidebarOpen(false)}
        >
          <X size={20} />
        </button>
      </div>

      {/* Nav */}
      <nav className="flex-1 px-4 space-y-1 mt-4 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = item.exact
            ? pathname === item.href
            : pathname === item.href || (item.href !== "/dashboard/instructor/courses" && pathname.startsWith(item.href));
          return (
            <Link
              key={item.name}
              href={item.href}
              className={`flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                isActive
                  ? "bg-primary text-white shadow-lg shadow-primary/20"
                  : "text-muted-foreground hover:bg-muted hover:text-foreground"
              }`}
            >
              <item.icon size={19} />
              <span className="font-medium">{item.name}</span>
              {isActive && <ChevronRight size={15} className="ml-auto opacity-70" />}
            </Link>
          );
        })}

        {dbUser?.role === 'ADMIN' && (
          <div className="pt-4 mt-4 border-t border-border">
            <p className="px-4 text-[10px] font-bold text-muted-foreground uppercase tracking-widest mb-2">Admin Tools</p>
            <Link
              href="/dashboard/student"
              className="flex items-center space-x-3 px-4 py-3 rounded-xl text-muted-foreground hover:bg-muted hover:text-foreground transition-all"
            >
              <GraduationCap size={19} />
              <span className="font-medium">Student Mode</span>
            </Link>
            <Link
              href="/dashboard/admin"
              className="flex items-center space-x-3 px-4 py-3 rounded-xl text-muted-foreground hover:bg-muted hover:text-foreground transition-all"
            >
              <LayoutDashboard size={19} />
              <span className="font-medium">Admin Panel</span>
            </Link>
          </div>
        )}
      </nav>

      {/* User footer */}
      <div className="p-4 border-t border-border">
        <div className="flex items-center space-x-3 mb-3 px-3">
          <div className="w-9 h-9 rounded-full bg-primary/20 flex items-center justify-center text-primary font-bold text-sm flex-shrink-0">
            {user?.displayName?.charAt(0) || user?.email?.charAt(0).toUpperCase() || "I"}
          </div>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-bold truncate">{user?.displayName || "Instructor"}</p>
            <div className="flex items-center space-x-1.5">
              <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${
                dbUser?.role === 'ADMIN' ? 'bg-primary text-white' : 'bg-muted text-muted-foreground'
              }`}>
                {dbUser?.role || 'INSTRUCTOR'}
              </span>
              <p className="text-[10px] text-muted-foreground truncate">{user?.email}</p>
            </div>
          </div>
        </div>
        <button
          onClick={() => { logout(); router.push("/"); }}
          className="flex items-center space-x-3 px-4 py-2.5 w-full rounded-xl text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-colors"
        >
          <LogOut size={18} />
          <span className="font-medium text-sm">Sign Out</span>
        </button>
      </div>
    </>
  );

  return (
    <ProtectedRoute allowedRoles={["INSTRUCTOR", "ADMIN"]}>
      <div className="min-h-screen bg-background flex">
        {/* Mobile overlay */}
        {sidebarOpen && (
          <div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-30 md:hidden"
            onClick={() => setSidebarOpen(false)}
          />
        )}

        {/* Sidebar */}
        <aside
          className={`
            fixed top-0 left-0 h-full w-64 z-40 bg-card border-r border-border flex flex-col transition-transform duration-300 ease-in-out
            ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}
            md:translate-x-0 md:static md:z-auto
          `}
        >
          <SidebarContent />
        </aside>

        {/* Main */}
        <div className="flex-1 flex flex-col min-w-0">
          {/* Mobile topbar */}
          <header className="md:hidden sticky top-0 z-20 bg-card/80 backdrop-blur-xl border-b border-border px-4 py-3 flex items-center justify-between">
            <button
              onClick={() => setSidebarOpen(true)}
              className="p-2 rounded-xl hover:bg-muted transition-colors"
              aria-label="Open menu"
            >
              <Menu size={22} />
            </button>
            <span className="font-bold text-lg">
              AI<span className="text-primary">Smart</span>
            </span>
            <div className="w-9 h-9 rounded-full bg-primary/20 flex items-center justify-center text-primary font-bold text-sm">
              {user?.displayName?.charAt(0) || "I"}
            </div>
          </header>

          <main className="flex-1 overflow-y-auto">
            <div className="p-6 md:p-8">{children}</div>
          </main>
        </div>
      </div>
    </ProtectedRoute>
  );
}

"use client";

import { useAuth } from "@/context/AuthContext";
import { motion } from "framer-motion";
import { Users, BookOpen, Star, TrendingUp, Loader2, Plus } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import api from "@/lib/api";
import toast from "react-hot-toast";

interface InstructorStats {
  coursesCount: number;
  totalStudents: number;
  recentEnrollments: any[];
  revenue: number;
}

interface CourseAnalytics {
  id: string;
  title: string;
  enrollments: number;
  recentEnrollments: number;
  avgProgress: number;
  revenue: number;
  rating: number;
}

export default function InstructorDashboard() {
  const { user, dbUser, loading: authLoading } = useAuth();
  const [stats, setStats] = useState<InstructorStats | null>(null);
  const [analytics, setAnalytics] = useState<CourseAnalytics[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!dbUser) return;
    const fetchData = async () => {
      try {
        const [statsRes, analyticsRes] = await Promise.all([
          api.get("/users/instructor-stats"),
          api.get("/users/instructor-course-analytics")
        ]);
        setStats(statsRes.data);
        setAnalytics(analyticsRes.data);
      } catch (err) {
        toast.error("Failed to load dashboard data");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [dbUser]);

  if (loading || authLoading) {
    return (
      <div className="space-y-8 animate-pulse">
        <div className="flex justify-between items-center">
          <div className="space-y-2">
            <div className="h-10 w-64 bg-muted rounded-lg" />
            <div className="h-4 w-48 bg-muted rounded-lg" />
          </div>
          <div className="h-12 w-48 bg-muted rounded-xl" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="h-32 bg-muted rounded-2xl border border-border/50" />
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="h-96 bg-muted rounded-3xl border border-border/50" />
          <div className="h-96 bg-muted rounded-3xl border border-border/50" />
        </div>
      </div>
    );
  }

  const statCards = [
    { name: "Total Students", value: stats?.totalStudents || 0, icon: Users, color: "text-foreground", bg: "bg-muted" },
    { name: "Active Courses", value: stats?.coursesCount || 0, icon: BookOpen, color: "text-primary", bg: "bg-primary/10" },
    { name: "Average Rating", value: "4.9", icon: Star, color: "text-foreground", bg: "bg-muted" },
    { name: "Total Revenue", value: `$${(stats?.revenue || 0).toFixed(2)}`, icon: TrendingUp, color: "text-foreground", bg: "bg-muted" },
  ];

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Instructor Dashboard</h1>
